/**
 * Kumva StartCampaign Node
 * Initializes campaign sessions and manages webhook callbacks
 */

module.exports = function(RED) {
  const { v4: uuidv4 } = require('uuid');
  const SessionManager = require('kumva-insights/utils/session-manager');
  const DataStorage = require('kumva-insights/utils/data-storage');
  const ConfigManager = require('kumva-insights/utils/config-manager');
  const helpers = require('kumva-insights/utils/helpers');

  // Global session manager and storage (shared across instances)
  let globalSessionManager = null;
  let globalDataStorage = null;
  let globalConfigManager = null;

  /**
   * Initialize global dependencies
   */
  async function initializeGlobals() {
    if (!globalSessionManager) {
      const configManager = new ConfigManager();
      globalConfigManager = configManager;
      
      globalSessionManager = new SessionManager(configManager.getRedisConfig());
      await globalSessionManager.initialize();

      globalDataStorage = new DataStorage(configManager.getStoragePath());
    }

    return {
      sessionManager: globalSessionManager,
      dataStorage: globalDataStorage,
      configManager: globalConfigManager
    };
  }

  function KumvaStartCampaignNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;

    // Initialize globals on first creation
    initializeGlobals().catch(error => {
      node.error(`Failed to initialize: ${error.message}`);
    });

    /**
     * Handle incoming messages
     */
    node.on('input', async function(msg) {
      try {
        const { sessionManager, dataStorage, configManager } = await initializeGlobals();

        // Validate required input
        if (!msg.phoneNumber) {
          node.error('Missing phoneNumber in message');
          return;
        }

        if (!msg.campaignId) {
          node.error('Missing campaignId in message');
          return;
        }

        // Generate session ID
        const sessionId = `session_${msg.campaignId}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

        // Parse timeout
        const timeoutSeconds = helpers.timeToSeconds(config.sessionTimeout || '3600s');

        // Create session data
        const sessionData = {
          sessionId: sessionId,
          phoneNumber: msg.phoneNumber,
          campaignId: msg.campaignId,
          campaignType: config.campaignType || 'sms',
          shortCode: config.shortCode || null,
          status: 'active',
          createdAt: new Date().toISOString(),
          contactData: msg.contactData || {},
          initialMessage: msg.initialMessage || '',
          debugMode: config.debugMode || false,
          _kumvaMetadata: {
            nodeId: node.id,
            flowId: RED.settings.context?.global?.flowId || 'unknown'
          }
        };

        // Create session in Redis
        const sessionResult = await sessionManager.createSession(
          sessionId,
          sessionData,
          timeoutSeconds
        );

        if (!sessionResult.success) {
          node.error(`Failed to create session: ${sessionResult.error}`);
          node.status({
            fill: 'red',
            shape: 'ring',
            text: 'Session creation failed'
          });
          return;
        }

        // If storing responses is enabled, create entry in data storage
        if (config.storeResponses) {
          const storageResult = await dataStorage.createUserSession(
            msg.campaignId,
            msg.phoneNumber,
            sessionData
          );

          if (!storageResult.success) {
            node.warn(`Failed to store session: ${storageResult.error}`);
            // Don't fail the flow, just log warning
          }
        }

        // Log session creation
        if (config.debugMode) {
          node.log(`Session created: ${sessionId}`);
          node.log(`Phone: ${msg.phoneNumber}`);
          node.log(`Campaign: ${msg.campaignId}`);
        }

        // Prepare output message
        const outputMsg = {
          ...msg,
          sessionId: sessionId,
          campaignStatus: 'initialized',
          _kumva: {
            ...msg._kumva,
            sessionId: sessionId,
            sessionTimeout: timeoutSeconds
          }
        };

        // Update node status
        node.status({
          fill: 'green',
          shape: 'dot',
          text: `Session: ${sessionId.substring(0, 12)}...`
        });

        // Send message to next node
        node.send(outputMsg);

      } catch (error) {
        node.error(`Error in StartCampaign node: ${error.message}`);
        node.status({
          fill: 'red',
          shape: 'ring',
          text: 'Error'
        });
      }
    });

    /**
     * Handle close/cleanup
     */
    node.on('close', function(done) {
      // Don't close session manager as it's shared
      done();
    });

    // Initialize status
    node.status({
      fill: 'yellow',
      shape: 'ring',
      text: 'Ready'
    });
  }

  /**
   * Webhook handler for incoming callbacks from Africa's Talking
   */
  function KumvaWebhookHandler() {
    RED.httpAdmin.post('/kumva/webhook', async function(req, res) {
      try {
        const { sessionManager, dataStorage, configManager } = await initializeGlobals();

        const callbackData = req.body;

        // Log webhook data if available
        RED.log.debug(`Webhook received: ${JSON.stringify(callbackData)}`);

        // Identify session from callback data
        // Africa's Talking includes sessionId or we can map from phone number + campaign
        let sessionId = callbackData.sessionId;
        
        if (!sessionId && callbackData.phoneNumber && callbackData.campaignId) {
          // Try to find session by phone and campaign
          sessionId = `session_${callbackData.campaignId}_${callbackData.phoneNumber}`;
        }

        if (!sessionId) {
          RED.log.warn('Could not identify session from webhook data');
          res.status(400).json({ success: false, error: 'No session identifier' });
          return;
        }

        // Get session
        const sessionResult = await sessionManager.getSession(sessionId);

        if (!sessionResult.exists) {
          RED.log.warn(`Session not found: ${sessionId}`);
          res.status(404).json({ success: false, error: 'Session not found' });
          return;
        }

        const session = sessionResult.data;

        // Handle different callback types
        let responseData = {
          content: callbackData.text || callbackData.message || '',
          type: callbackData.type || 'text',
          dtmfInput: callbackData.dtmfInput || null,
          rawData: callbackData
        };

        // Store response if enabled
        if (session.storeResponses) {
          const storeResult = await sessionManager.storeResponse(sessionId, responseData);
          
          if (!storeResult.success) {
            RED.log.warn(`Failed to store response: ${storeResult.error}`);
          }
        }

        // Update session status
        await sessionManager.updateSession(sessionId, {
          status: 'awaiting-response',
          lastResponse: responseData,
          lastUpdated: new Date().toISOString()
        });

        // Find the node handling this session and inject the response
        const nodes = RED.nodes.getFlows()[0].nodes || [];
        const relevantNode = nodes.find(n => 
          n.type === 'kumva-wait-for-response' &&
          n._kumva?.sessionId === sessionId
        );

        if (relevantNode && relevantNode._inputCallback) {
          // Trigger the waiting node with the response
          relevantNode._inputCallback(responseData);
        }

        // Acknowledge receipt
        res.json({ success: true, sessionId: sessionId });

      } catch (error) {
        RED.log.error(`Webhook error: ${error.message}`);
        res.status(500).json({ success: false, error: error.message });
      }
    });
  }

  RED.nodes.registerType('kumva-start-campaign', KumvaStartCampaignNode);

  // Register webhook handler when first node is added
  RED.events.once('flows:add', function() {
    KumvaWebhookHandler();
  });
};